/**
 * @hidden
 */
export class PivotGridState {
    columnAxes;
    rowAxes;
    measureAxes;
    sort;
    filter;
    constructor(columnAxes, rowAxes, measureAxes, sort, filter) {
        this.columnAxes = columnAxes;
        this.rowAxes = rowAxes;
        this.measureAxes = measureAxes;
        this.sort = sort;
        this.filter = filter;
    }
}
